(function(g){'use strict';const KEY='tls-save-v2',BACKUP='tls-save-backup';g.TLS_SAVE={has(){return!!localStorage.getItem(KEY)},save(state){try{let payload=JSON.stringify({schema:2,savedAt:Date.now(),state});localStorage.setItem(BACKUP,localStorage.getItem(KEY)||payload);localStorage.setItem(KEY,payload);return true}catch{return false}},load(){for(let key of[KEY,BACKUP])try{let p=JSON.parse(localStorage.getItem(key));if(p&&p.schema===2&&p.state?.player)return p.state}catch{}return null},meta(){try{let p=JSON.parse(localStorage.getItem(KEY));return p?{savedAt:p.savedAt,level:p.state.player.level,day:p.state.world.day}:null}catch{return null}},clear(){localStorage.removeItem(KEY);localStorage.removeItem(BACKUP)},export(){return localStorage.getItem(KEY)||''}}})(window);
